153	+        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
154	+        BigDecimal totalTax = BigDecimal.ZERO.setScale(2);
155	+        for (Reservation reservation : paidReservations) {
156	+            int nights = reservation.price().nights();
157	+            int guests = reservation.guests();
